L9_1 = "\226\128\166\226\128\166\235\132\164. \236\156\181\237\149\169\236\178\180\235\165\188 \235\179\180\234\179\160 \235\139\185\236\139\160\235\182\128\237\132\176 \235\150\160\236\152\172\235\158\144\236\163\160. \237\149\152\236\157\180\235\147\156\235\166\172\237\158\136 \236\134\140\236\158\165."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "\226\128\166\226\128\166\227\129\175\227\129\132\227\128\130\232\158\141\229\144\136\228\189\147\227\130\146\232\166\139\227\129\166\227\129\190\227\129\154\227\129\130\227\129\170\227\129\159\227\129\140\230\128\157\227\129\132\230\181\174\227\129\139\227\129\179\227\129\190\227\129\151\227\129\159\227\128\130\227\131\143\227\130\164\227\131\137\227\131\170\227\131\146\230\137\128\233\149\183\227\128\130"
L8_1.m_Talk_JPN = L9_1
L9_1 = "...Yes. I knew it was your doing when I saw the hybriders, Chief Heydrich."
L8_1.m_Talk_ENG = L9_1
L9_1 = "\226\128\166\226\128\166\229\151\175\239\188\140\231\156\139\229\136\176\232\158\141\229\144\136\233\171\148\239\188\140\230\136\145\229\176\177\229\133\136\230\131\179\229\136\176\228\189\160\228\186\134\239\188\140\230\181\183\229\190\183\233\135\140\229\184\140\230\137\128\233\149\183\227\128\130"
L8_1.m_Talk_TWN = L9_1
L9_1 = "\224\184\132\224\185\136\224\184\176 \224\184\149\224\184\173\224\184\153\224\185\128\224\184\171\224\185\135\224\184\153\224\185\132\224\184\174\224\184\154\224\184\163\224\184\180\224\185\128\224\184\148\224\184\173\224\184\163\224\185\140\224\184\137\224\184\177\224\184\153\224\184\129\224\185\135\224\184\163\224\184\185\224\185\137\224\185\129\224\184\165\224\185\137\224\184\167\224\184\167\224\185\136\224\184\178\224\184\157\224\184\181\224\184\161\224\184\183\224\184\173\224\184\132\224\184\184\224\184\147 \224\184\171\224\184\177\224\184\167\224\184\171\224\184\153\224\185\137\224\184\178\224\185\128\224\184\174\224\184\162\224\185\140\224\184\148\224\184\163\224\184\180\224\184\138"
L8_1.m_Talk_THA = L9_1
L9_1 = "\196\144\195\186ng. T\195\180i \196\145\195\163 bi\225\186\191t l\195\160 do \195\180ng k\225\187\131 t\225\187\171 khi th\225\186\165y nh\225\187\175ng k\225\186\187 lai t\225\186\161o n\195\160y, Tr\198\176\225\187\159ng Ban Heydrich \225\186\161."
L8_1.m_Talk_VTN = L9_1
L9_1 = "\226\128\166\226\128\166\229\151\175\239\188\140\231\156\139\229\136\176\232\158\141\229\144\136\228\189\147\239\188\140\230\136\145\229\176\177\229\133\136\230\131\179\229\136\176\228\189\160\228\186\134\239\188\140\230\181\183\229\190\183\233\135\140\229\184\140\233\131\168\233\149\191\227\128\130"
L8_1.m_Talk_SCN = L9_1
L9_1 = "... Ja. Als ich die Hybriden sah, wusste ich, dass Sie dahinter stecken, General Heydrich."
L8_1.m_Talk_DEU = L9_1
L9_1 = "... En effet, Heydrich. J'ai su que c'\195\169tait vous qui \195\169tiez derri\195\168re cette affaire quand j'ai vu les hybrides."
