L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "\227\129\181\227\129\181\227\129\163\227\128\129\227\129\147\227\129\174\227\130\136\227\129\134\227\129\170\229\189\162\227\129\167\227\129\138\228\188\154\227\129\132\227\129\153\227\130\139\227\129\168\227\129\175\230\174\139\229\191\181\227\129\167\227\129\153\227\129\173\227\128\129\229\137\175\229\173\166\228\188\154\233\149\183\227\128\130"
