L12_1 = "Heh. It's a shame we had to meet like this, Ms. Vice President."
L11_1.m_Talk_ENG = L12_1
L12_1 = "\229\145\181\229\145\181\239\188\140\229\190\136\233\129\186\230\134\190\230\136\145\229\128\145\231\171\159\231\132\182\228\187\165\233\128\153\231\168\174\230\150\185\229\188\143\232\166\139\233\157\162\239\188\140\229\137\175\229\173\184\230\156\131\233\149\183\227\128\130"
L11_1.m_Talk_TWN = L12_1
L12_1 = "\224\185\128\224\184\174\224\184\173\224\184\176 \224\184\153\224\185\136\224\184\178\224\185\128\224\184\170\224\184\181\224\184\162\224\184\148\224\184\178\224\184\162\224\184\136\224\184\177\224\184\135\224\184\153\224\184\176\224\184\151\224\184\181\224\185\136\224\184\149\224\185\137\224\184\173\224\184\135\224\184\161\224\184\178\224\185\128\224\184\136\224\184\173\224\184\129\224\184\177\224\184\153\224\185\129\224\184\154\224\184\154\224\184\153\224\184\181\224\185\137 \224\184\163\224\184\173\224\184\135\224\184\155\224\184\163\224\184\176\224\184\152\224\184\178\224\184\153"
L11_1.m_Talk_THA = L12_1
L12_1 = "He. Th\225\186\173t \196\145\195\161ng x\225\186\165u h\225\187\149 khi ch\195\186ng ta ph\225\186\163i g\225\186\183p nhau nh\198\176 th\225\186\191 n\195\160y, Ph\195\179 Ch\225\187\167 T\225\187\139ch."
L11_1.m_Talk_VTN = L12_1
L12_1 = "\229\145\181\229\145\181\239\188\140\229\190\136\233\129\151\230\134\190\230\136\145\228\187\172\231\171\159\231\132\182\228\187\165\232\191\153\231\167\141\230\150\185\229\188\143\232\167\129\233\157\162\239\188\140\229\137\175\228\188\154\233\149\191\227\128\130"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Hihi. Es ist echt schade, dass wir uns auf diese Weise treffen mussten, stellvertretende Gesellschaftsvorsitzende."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Hu hu. J'esp\195\169rais vous rencontrer dans de meilleures circonstances, vice-pr\195\169sidente."
