L12_1.m_Talk_VTN = L13_1
L13_1 = "\226\128\166\226\128\166\233\156\178\229\168\156\239\188\159\228\189\160\228\184\186\228\187\128\228\185\136\229\156\168\233\130\163\229\132\191\239\188\159"
